available-captures-for-rook:
class Solution:
    def numRookCaptures(self, board: List[List[str]]) -> int:
        for i in range(8):
            for j in range(8):
                if board[i][j] == 'R':
                    ans = 0
                    for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
                        ni, nj = i+di, j+dj
                        while 0 <= ni < 8 and 0 <= nj < 8:
                            if board[ni][nj] == 'B': break
                            if board[ni][nj] == 'p': ans += 1; break
                            ni += di; nj += dj
                    return ans
        return 0

