binary-search:
class Solution:
    def search(self, nums: List[int], target: int) -> int:
        l, r = 0, len(nums)-1
        while l <= r:
            m = (l+r)//2
            if nums[m] == target: return m
            if nums[m] < target: l = m+1
            else: r = m-1
        return -1

binary-tree-tilt:
class Solution:
    def findTilt(self, root: Optional[TreeNode]) -> int:
        self.total = 0
        def go(node):
            if not node:
                return 0
            l = go(node.left)
            r = go(node.right)
            self.total += abs(l - r)
            return l + r + node.val
        go(root)
        return self.total

