class Solution:
    def getNoZeroIntegers(self, n: int) -> List[int]:
        def nz(x):
            return '0' not in str(x)
        for a in range(1, n):
            if nz(a) and nz(n - a):
                return [a, n - a]
        return [1, n - 1]

