class Solution:
    def findMissingAndRepeatedValues(self, grid: List[List[int]]) -> List[int]:
        n = len(grid)
        seen = set()
        dup = -1
        for row in grid:
            for x in row:
                if x in seen: dup = x
                seen.add(x)
        total = n*n
        for i in range(1, total+1):
            if i not in seen: return [dup, i]
        return [dup, -1]

find-mode-in-binary-search-tree:
class Solution:
    def findMode(self, root: Optional[TreeNode]) -> List[int]:
        from collections import Counter
        c = Counter()
        def go(node):
            if not node:
                return
            c[node.val] += 1
            go(node.left)
            go(node.right)
        go(root)
        m = max(c.values())
        return [k for k, v in c.items() if v == m]

