class Solution:
    def islandPerimeter(self, grid: List[List[int]]) -> int:
        R, C = len(grid), len(grid[0])
        peri = 0
        for i in range(R):
            for j in range(C):
                if grid[i][j] == 1:
                    peri += 4
                    for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
                        ni, nj = i+di, j+dj
                        if 0 <= ni < R and 0 <= nj < C and grid[ni][nj] == 1:
                            peri -= 1
        return peri

