        nums.sort()
        pref = [0]
        for x in nums: pref.append(pref[-1]+x)
        res = []
        for q in queries:
            lo, hi = 0, len(pref)-1
            while lo <= hi:
                mid = (lo+hi)//2
                if pref[mid] <= q: lo = mid+1
                else: hi = mid-1
            res.append(hi)
        return res

