    def toLowerCase(self, s: str) -> str:
        return s.lower()

toeplitz-matrix:
class Solution:
    def isToeplitzMatrix(self, matrix: List[List[int]]) -> bool:
        return all(matrix[i][j] == matrix[i-1][j-1] for i in range(1, len(matrix)) for j in range(1, len(matrix[0])))

transpose-matrix:
class Solution:
    def transpose(self, matrix: List[List[int]]) -> List[List[int]]:
        R, C = len(matrix), len(matrix[0])
        return [[matrix[r][c] for r in range(R)] for c in range(C)]

two-sum-ii-input-array-is-sorted:
class Solution:
    def twoSum(self, numbers: List[int], target: int) -> List[int]:
        l, r = 0, len(numbers)-1
        while l < r:
            s = numbers[l]+numbers[r]
            if s == target: return [l+1, r+1]
            if s < target: l += 1
            else: r -= 1
        return []

two-sum-iv-input-is-a-bst:
# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def findTarget(self, root: Optional[TreeNode], k: int) -> bool:
        seen = set()
        def dfs(n):
            if not n: return False
            if k - n.val in seen: return True
            seen.add(n.val)
            return dfs(n.left) or dfs(n.right)
        return dfs(root)

ugly-number:
class Solution:
    def isUgly(self, n: int) -> bool:
        if n <= 0: return False
        for p in (2, 3, 5):
            while n % p == 0:
                n //= p
        return n == 1

uncommon-words-from-two-sentences:
class Solution:
    def uncommonFromSentences(self, s1: str, s2: str) -> List[str]:
        from collections import Counter
        c = Counter((s1 + ' ' + s2).split())
        return [w for w, n in c.items() if n == 1]

unique-email-addresses:
class Solution:
    def numUniqueEmails(self, emails: List[str]) -> int:
        seen = set()
        for e in emails:
            local, dom = e.split('@')
            local = local.split('+')[0].replace('.', '')
            seen.add(local + '@' + dom)
        return len(seen)

univalued-binary-tree:
# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def isUnivalTree(self, root: Optional[TreeNode]) -> bool:
        def dfs(n, v):
            if not n: return True
            return n.val == v and dfs(n.left, v) and dfs(n.right, v)
        return dfs(root, root.val)

valid-anagram:
class Solution:
    def isAnagram(self, s: str, t: str) -> bool:
        return sorted(s) == sorted(t)

valid-boomerang:
class Solution:
    def isBoomerang(self, points: List[List[int]]) -> bool:
        (x1,y1),(x2,y2),(x3,y3) = points
        return (x2-x1)*(y3-y1)-(y2-y1)*(x3-x1) != 0

valid-palindrome:
class Solution:
    def isPalindrome(self, s: str) -> bool:
        t = [ch.lower() for ch in s if ch.isalnum()]
        return t == t[::-1]

valid-palindrome-ii:
class Solution:
    def validPalindrome(self, s: str) -> bool:
        def is_pal(lo, hi):
            while lo < hi:
                if s[lo] != s[hi]: return False
                lo += 1; hi -= 1
            return True
        i, j = 0, len(s) - 1
        while i < j:
            if s[i] != s[j]:
                return is_pal(i+1, j) or is_pal(i, j-1)
            i += 1; j -= 1
        return True

valid-perfect-square:
class Solution:
    def isPerfectSquare(self, num: int) -> bool:
        l, r = 0, num
        while l <= r:
            m = (l+r)//2
            sq = m*m
            if sq == num: return True
            if sq < num: l = m+1
            else: r = m-1
        return False

verifying-an-alien-dictionary:
class Solution:
    def isAlienSorted(self, words: List[str], order: str) -> bool:
        rank = {c: i for i, c in enumerate(order)}
        for a, b in zip(words, words[1:]):
            for ca, cb in zip(a, b):
                if rank[ca] < rank[cb]: break
                elif rank[ca] > rank[cb]: return False
            else:
                if len(a) > len(b): return False
        return True

word-pattern:
class Solution:
    def wordPattern(self, pattern: str, s: str) -> bool:
        words = s.split()
        if len(pattern) != len(words): return False
        m1, m2 = {}, {}
        for p, w in zip(pattern, words):
            if p in m1 and m1[p] != w: return False
            if w in m2 and m2[w] != p: return False
            m1[p] = w; m2[w] = p
        return True

word-search:
class Solution:
    def exist(self, board: List[List[str]], word: str) -> bool:
        R, C = len(board), len(board[0])
        def dfs(i, j, k):
            if k == len(word): return True
            if i < 0 or j < 0 or i >= R or j >= C or board[i][j] != word[k]: return False
            tmp = board[i][j]
            board[i][j] = '#'
            for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
                if dfs(i+di, j+dj, k+1): return True
            board[i][j] = tmp
            return False
        for i in range(R):
            for j in range(C):
                if dfs(i, j, 0): return True
        return False

xor-operation-in-an-array:
class Solution:
    def xorOperation(self, n: int, start: int) -> int:
        r =  0
        for i in range(n):
            r ^= start + 2*i
        return r
